@page { size: 480px 288px; margin: 0; }
html, body { margin: 0; padding: 0; }
body { font-family: 'Noto Sans'; font-size: 16px; line-height: 24px; color: #184d36; }
p { margin: 24px; width: 420px; }
.accent { color: #254fa0; }
a { color: #254fa0; text-decoration: underline; }
strong { font-weight: 700; font-synthesis: none; }
em { font-style: italic; font-synthesis: none; }
p::first-letter { float: left; font-size: 56px; line-height: 1;
font-weight: 400; color: #bc6c25; background: #ffe080;
border: 2px solid #e04020; padding: 2px; margin: 0 8px 0 0; }

